class SoloReplayAndIdTests(unittest.TestCase):
 def setUp(self):
  p=patch.dict('os.environ',{'GETNET_WEB_SEARCH':'0'});p.start();self.addCleanup(p.stop)
  self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup);self.service=ContextService(Store(Path(self.tmp.name)/'state.sqlite'));self.sid=self.service.create('synthetic_A')
 def test_preflight_claim_ids_never_enter_model_payload_or_final_claim(self):
  text='A Smart do caixa da Loja Cedro está sem internet.'
  self.service.step('synthetic_A',self.sid,text,proposal=proposal(text,[obs(text,'connected','false')],[{'ref':'a','label':'Smart do caixa','store':'Loja Cedro','quote':text}]))
  good='Selecionei a rede na Smart do caixa.';unclear='A Smart do caixa continua com problema.';message=good+' '+unclear
  p=proposal(message,[obs(good,'network_selected','true'),obs(unclear,'connected','true')]);client=Sequence([p,{'devices':[],'observations':[{'index':1,'verdict':'unsupported','origin':'hypothesis'}]}]);self.service.interpreter=SoloInterpreter(client)
  original=state_module.uuid4;generated=[]
  def traced_uuid():
   value=original();generated.append('claim_'+value.hex);return value
  with patch.object(state_module,'uuid4',side_effect=traced_uuid):result=self.service.step('synthetic_A',self.sid,message)
  self.assertEqual(len(client.payloads),2);self.assertGreaterEqual(len(generated),2)
  self.assertNotIn(generated[0],json.dumps(client.payloads));self.assertFalse(any(f['assertion_id']==generated[0] for f in result['state']['facts'].values()))
  final=next(f for f in result['state']['facts'].values() if f['field']=='network_selected');self.assertEqual(final['assertion_id'],generated[-1]);self.assertEqual(self.service.state('synthetic_A',self.sid),result['state'])
 def test_real_H05_second_turn_replay_clears_unknown_pending(self):
  self.service.store.commit('synthetic_A',self.sid,0,copy.deepcopy(FIXTURE['before']));client=Sequence(FIXTURE['outputs']);self.service.interpreter=SoloInterpreter(client)
  result=self.service.step('synthetic_A',self.sid,FIXTURE['message'])
  self.assertEqual(result['state']['pending'],[]);self.assertNotIn('A qual aparelho',result['answer'])
  restarts=[f for f in result['state']['facts'].values() if f['field']=='restart_attempted'];self.assertTrue(any(f['entity']=='new2' and f['value']=='true' and f['origin']=='customer' for f in restarts));self.assertTrue(any(f['entity']=='new1' and f['value']=='false' for f in restarts))
 def test_pending_not_cleared_without_grounded_new_fact(self):
  self.service.store.commit('synthetic_A',self.sid,0,copy.deepcopy(FIXTURE['before']));pid=FIXTURE['before']['pending'][0]['id'];text='Continue o resumo.'
  result=self.service.step('synthetic_A',self.sid,text,proposal=proposal(text,pending=[pid]));self.assertEqual([x['id'] for x in result['state']['pending']],[pid])
if __name__=='__main__':unittest.main(verbosity=2)
